style.css:
@-moz-document url-prefix("https://www.roblox.com/") {
html, body {
        background: url("https://i.pinimg.com/736x/8d/b7/87/8db7873868b7c6ad1059cd6098d90c90.jpg") no-repeat center center fixed !important;
        background-size: cover !important;
        background-color: transparent !important;
    }

    /* Elimină fundalurile albe de pe toate elementele */
    body * {
        background-color: transparent !important;
    }

    /* Schimbă culoarea textului ca să fie vizibil pe fundal întunecat */
    body, body * {
        color: #ffffff !important;
    }
}
